WITH joined AS (SELECT s.*, b.shipping_fee, b.status AS order_status, b.channel FROM shipments s INNER JOIN orders b ON s.order_id <=> b.id) SELECT s.id, s.order_id, s.carrier, s.shipped_date, s.status, s.order_status, s.channel, CASE WHEN status RLIKE '^(RETURNED|DELIVERED)$' THEN 'OTHER_ZONE' WHEN status RLIKE '^(IN_TRANSIT|LOST)$' THEN 'PRIORITY' ELSE 'GROUP_A' END AS status_zone, (SELECT MIN(t2.quantity) FROM order_items t2 WHERE t2.order_id = s.order_id) AS min_order_item_quantity FROM joined s;
